<?php
require __DIR__."/vendor/autoload.php";
use PhpCsFixer\Tokenizer\Tokens;
use PhpCsFixer\Fixer\StringNotation\SimpleToComplexStringVariableFixer;
use PhpCsFixer\Linter\Linter;

$fixer = new SimpleToComplexStringVariableFixer();
$cases = [
    ["<?php\n$name = \"World\";\necho \"Hello \${name}!\";", "<?php\n\$name = \"World\";\necho \"Hello {\$name}!\";"],
    ["<?php\n\$name = \"World\";\necho \"Hello \${name[\x27key\x27]}!\";", "<?php\n\$name = \"World\";\necho \"Hello {\$name[\x27key\x27]}!\";"],
    ["<?php\n\$name = \"World\";\necho \"Hello \${name[0]}!\";", "<?php\n\$name = \"World\";\necho \"Hello {\$name[0]}!\";"],
];
foreach ($cases as $i => [$input, $expected]) {
    $tokens = Tokens::fromCode($input);
    $file = new SplFileInfo("/tmp/x.php");
    $fixer->fix($file, $tokens);
    $out = $tokens->generateCode();
    echo $out === $expected ? "OK $i\n" : "FAIL $i\n--- got ---\n$out\n--- expected ---\n$expected\n";
}
EOF
php /tmp/check.php'

